void send(Message m) {
  spool_write_and_fsync(m);                       // durable before the wire
  asio::async_write(sock, asio::buffer(m.bytes), [m](error_code ec, size_t) {
    if (ec) return;
    asio::async_read_until(sock, ack_buf, '\n', [m](error_code ec2, size_t) {
      if (!ec2) std::filesystem::remove(spool_path(m.id));  // ack -> forget
    });
  });
}
